 vec2 s = texsize.xy / min(texsize.x, texsize.y);
 vec2 p = (uv - 0.5) * s;
 vec3 m = texture(sampler_main, uv).xyz;
 vec3 b1 = GetBlur1(uv);
 vec3 b2 = GetBlur2(uv);
 vec3 col = m + max(b1 - 0.3, 0.0) * 0.5 + max(b2 - 0.22, 0.0) * (0.6 + 0.6 * q3);
 col = 1.0 - exp(-col * 1.35);
 col *= 0.8 + 0.2 * smoothstep(1.3, 0.3, length(p));
 ret = col;
}
